// Byte-operation adapter of the former private decoded request and Profile
// path helper. Live mapping/profile access is replaced by borrowed fields.
use alloc::{format,string::String,vec::Vec};
use charlotte_protocol_s3::ObjectRequest;
#[derive(Clone)]
pub struct OwnedRequest {
 pub flags:u16,pub content_length:u64,pub range_start:u64,pub range_end:u64,
 pub payload_sha256:[u8;32],key:Vec<u8>,
}
impl OwnedRequest {
 pub fn decode(bytes:&[u8])->Option<Self>{
  let request=ObjectRequest::decode(bytes)?;
  Some(Self{flags:request.flags,content_length:request.content_length,range_start:request.range_start,range_end:request.range_end,payload_sha256:request.payload_sha256,key:request.key.to_vec()})
 }
 pub fn key(&self)->&[u8]{&self.key}
 pub fn object_path(&self,bucket:&str,prefix:&str)->Option<String>{
  let key=core::str::from_utf8(&self.key).ok()?;
  if key.starts_with('/') || key.as_bytes().contains(&0) || key.split('/').any(|part|part=="."||part=="..") {return None;}
  let mut path=format!("/{}/",bucket);
  if !prefix.is_empty(){path.push_str(prefix.trim_end_matches('/'));path.push('/');}
  path.push_str(key);Some(path)
 }
}

